using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;

// Provided infrastructure — do not modify.
public sealed class TinyContainer
{
    private readonly System.Collections.Generic.Dictionary<System.Type, Func<object>> _factories = new();

    public void Register<TService>(Func<TService> factory) =>
        RegisterTransient(factory);

    public void RegisterTransient<TService>(Func<TService> factory) =>
        _factories[typeof(TService)] = () => factory()!;

    public void RegisterSingleton<TService>(Func<TService> factory)
    {
        object? instance = null;
        _factories[typeof(TService)] = () =>
        {
            if (instance is null) instance = factory()!;
            return instance;
        };
    }

    public TService Resolve<TService>()
    {
        if (!_factories.TryGetValue(typeof(TService), out var factory))
            throw new System.InvalidOperationException("no registration for " + typeof(TService).Name);
        return (TService)factory();
    }
}

